android.extraProguardRules:
# ==================================================================
# Svara Yoga — ProGuard/R8 keep rules
# ==================================================================
# Prevents R8 from stripping classes reached only via reflection or
# via string references in AndroidManifest.xml. Without these, the
# release build silently loses scheduled notifications, IAP callbacks,
# and native module bridges.

# --- expo-notifications ---
# BroadcastReceivers are declared in the manifest by string name,
# so R8's static analysis doesn't see them as reachable.
-keep class expo.modules.notifications.** { *; }
-keep class expo.modules.notifications.notifications.model.** { *; }
-keep class expo.modules.notifications.service.** { *; }
-keep class expo.modules.notifications.notifications.triggers.** { *; }
-keep class expo.modules.notifications.notifications.channels.** { *; }
-keep class expo.modules.notifications.tokens.** { *; }

# Serialization — expo-notifications persists scheduled requests
# to disk and deserializes them at boot via reflection.
-keepclassmembers class * implements java.io.Serializable {
    static final long serialVersionUID;
    private static final java.io.ObjectStreamField[] serialPersistentFields;
    !static !transient <fields>;
    private void writeObject(java.io.ObjectOutputStream);
    private void readObject(java.io.ObjectInputStream);
    java.lang.Object writeReplace();
    java.lang.Object readResolve();
}

# --- react-native-iap 15.x + nitro-modules ---
# Nitro uses JSI bindings resolved by string name at runtime.
-keep class com.dooboolab.rniap.** { *; }
-keep class com.margelo.nitro.** { *; }
-keep class com.hyperjeff.rniap.** { *; }
-keep interface com.margelo.nitro.** { *; }
-keepclassmembers class com.margelo.nitro.** { native <methods>; }

# --- react-native-async-storage ---
-keep class com.reactnativecommunity.asyncstorage.** { *; }

# --- expo-location ---
-keep class expo.modules.location.** { *; }

# --- expo-modules-core (autolinking) ---
# Modules are discovered via reflection based on annotations.
-keep @expo.modules.core.interfaces.** class * { *; }
-keep class * extends expo.modules.kotlin.modules.Module { *; }
-keepclassmembers class * {
    @expo.modules.kotlin.functions.Function <methods>;
    @expo.modules.kotlin.events.EventObserver <methods>;
}

# --- React Native core reflection safety ---
-keep class com.facebook.react.turbomodule.** { *; }
-keep class com.facebook.react.bridge.** { *; }
-keep class * extends com.facebook.react.bridge.ReactContextBaseJavaModule { *; }
-keep class * extends com.facebook.react.bridge.NativeModule { *; }
-keepclassmembers,includedescriptorclasses class * { native <methods>; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod <methods>; }

# --- Suppress warnings for missing optional platform code ---
-dontwarn okio.**
-dontwarn okhttp3.**
-dontwarn javax.annotation.**
-dontwarn org.conscrypt.**
